function demoMain(idx,label){
  var scenarios=[["login","valid creds","dashboard shown"],["checkout","item in cart","order confirmed"],["search","query typed","results listed"]];
  var s=scenarios[idx%scenarios.length];
  var givenOk=s[1].length>0, thenOk=s[2].indexOf(" ")>0;
  return "["+label+"] Scenario: "+s[0]+" | Given "+s[1]+" | Then "+s[2]+" => "+(givenOk&&thenOk?"ACCEPTED":"REJECTED");
}

